**Команда `/mycards` (handler `handlers/mycards.py`):**

```python
@router.message(Command("mycards"))
async def cmd_mycards(message: Message, reader: FirebirdReader):
    cards = await reader.patient_cards_by_phone(message.contact.phone_number)  # телефон известен из контекста / БД
    if not cards:
        return await message.answer("Карт не найдено. Нажмите «Поделиться контактом» в меню, чтобы привязать.")

    lines = ["📋 Ваши карты:"]
    for c in cards:
        lines.append(f"\n🆔 Карта #{c.card_id} — {c.full_name}")
        visits = await reader.visits_by_card(c.card_id, limit=5)
        if visits:
            lines.append("   Последние визиты:")
            for v in visits:
                lines.append(f"   • {v.dt:%d.%m.%Y} {v.doctor} — {v.service}")
        else:
            lines.append("   Визитов нет")
    await message.answer("\n".join(lines))
```

